// swift-tools-version: 6.2
import PackageDescription

// Measures Claude Code cold/warm start over stream-json and records fixtures.
let package = Package(
    name: "StreamProbe",
    platforms: [.macOS(.v26)],
    targets: [
        .target(name: "StreamJSON"),
        .executableTarget(name: "stream-probe", dependencies: ["StreamJSON"]),
        .testTarget(
            name: "StreamJSONTests",
            dependencies: ["StreamJSON"],
            resources: [.copy("../../Fixtures")]
        ),
    ]
)
----
import Foundation

/// Splits a byte stream into newline-terminated lines. Claude Code writes one JSON object per line.
public struct LineSplitter: Sendable {
    private var buffer = Data()

    public init() {}

    public mutating func append(_ chunk: Data) -> [Data] {
        buffer.append(chunk)
        var lines: [Data] = []
        while let nl = buffer.firstIndex(of: 0x0A) {
            let line = buffer[buffer.startIndex..<nl]
            if !line.isEmpty { lines.append(Data(line)) }
            buffer.removeSubrange(buffer.startIndex...nl)
        }
        return lines
    }
}

/// The minimal classification the probe needs: enough to time a turn and to tag fixtures.
/// The full typed model comes later; this stays deliberately loose.
public enum StreamEvent: Equatable, Sendable {
    case systemInit(sessionID: String, model: String, cwd: String, pluginErrors: Int?)
    case system(subtype: String)
    case partial(kind: String, deltaKind: String?)   // stream_event: event.type, event.delta.type
    case assistant(blockKinds: [String], parentToolUseID: String?)
    case user(blockKinds: [String])
    case rateLimit(status: String)
    case result(Result)
    case other(type: String)

    public struct Result: Equatable, Sendable {
        public var subtype: String
        public var isError: Bool
        public var sessionID: String
        public var durationMS: Int?
        public var ttftMS: Int?
        public var text: String?
    }

    public init?(line: Data) {
        guard let obj = try? JSONSerialization.jsonObject(with: line) as? [String: Any],
              let type = obj["type"] as? String else { return nil }
        let subtype = obj["subtype"] as? String
        switch (type, subtype) {
        case ("system", "init"):
            self = .systemInit(
                sessionID: obj["session_id"] as? String ?? "",
                model: obj["model"] as? String ?? "",
                cwd: obj["cwd"] as? String ?? "",
                pluginErrors: (obj["plugin_errors"] as? [Any])?.count)
        case ("system", let s?):
            self = .system(subtype: s)
        case ("stream_event", _):
            let ev = obj["event"] as? [String: Any] ?? [:]
            let delta = ev["delta"] as? [String: Any]
            self = .partial(kind: ev["type"] as? String ?? "?", deltaKind: delta?["type"] as? String)
        case ("assistant", _), ("user", _):
            let msg = obj["message"] as? [String: Any] ?? [:]
            let kinds = (msg["content"] as? [[String: Any]])?.compactMap { $0["type"] as? String } ?? []
            self = type == "assistant"
                ? .assistant(blockKinds: kinds, parentToolUseID: obj["parent_tool_use_id"] as? String)
                : .user(blockKinds: kinds)
        case ("rate_limit_event", _):
            let info = obj["rate_limit_info"] as? [String: Any] ?? [:]
            self = .rateLimit(status: info["status"] as? String ?? "?")
        case ("result", _):
            self = .result(Result(
                subtype: subtype ?? "?",
                isError: obj["is_error"] as? Bool ?? false,
                sessionID: obj["session_id"] as? String ?? "",
                durationMS: obj["duration_ms"] as? Int,
                ttftMS: obj["ttft_ms"] as? Int,
                text: obj["result"] as? String))
        default:
            self = .other(type: type)
        }
    }

    /// First user-visible answer text: a text_delta in a top-level (non-subagent) partial.
    public var isTextDelta: Bool {
        if case .partial("content_block_delta", "text_delta") = self { return true }
        return false
    }

    public var isAnyDelta: Bool {
        if case .partial("content_block_delta", _) = self { return true }
        return false
    }
}

/// Encodes one user turn for `--input-format stream-json`.
public func userMessageLine(_ text: String) -> Data {
    let obj: [String: Any] = [
        "type": "user",
        "message": ["role": "user", "content": [["type": "text", "text": text]]],
    ]
    var d = try! JSONSerialization.data(withJSONObject: obj)
    d.append(0x0A)
    return d
}

